import { indicatorFields } from "@/wab/client/components/style-controls/defined-indicator-inputs";
import { useCanvasComponentValue, type CanvasViewFieldRecipe } from "@/wab/client/components/canvas/canvas-view-inputs";
import type { TplNode, VariantSetting } from "@/wab/shared/model/classes";
import { useVariantComboInputs } from "@/wab/client/studio-ctx/variant-combo-inputs";
// This is a skeleton starter React component generated by Plasmic.
// This file is owned by you, feel free to edit as you see fit.
import { useContextMenu } from "@/wab/client/components/ContextMenu";
import {
  MenuBuilder,
  MenuItemContent,
} from "@/wab/client/components/menu-builder";
import {
  VariantSettingPopoverContent,
  VariantSettingPopoverTitle,
} from "@/wab/client/components/style-controls/DefinedIndicator";
import Chip from "@/wab/client/components/widgets/Chip";
import { UiText } from "@/wab/client/i18n/UiText";
import { PlasmicVariantComboRow } from "@/wab/client/plasmic/plasmic_kit_variants/PlasmicVariantComboRow";
import { ViewCtx } from "@/wab/client/studio-ctx/view-ctx";
import {
  VariantCombo,
} from "@/wab/shared/Variants";
import { isTplVariantable, summarizeTpl } from "@/wab/shared/core/tpls";
import { getEffectiveVariantSetting } from "@/wab/shared/effective-variant-setting";
import { Menu } from "antd";
import * as React from "react";

interface VariantComboRowProps {
  viewCtx: ViewCtx;
  combo: VariantCombo;
  onClick?: () => void;
  onActivate?: () => void;
}

const VariantComboRow = function VariantComboRow(
  props: VariantComboRowProps,
) {
  const { viewCtx, combo, onClick, onActivate } = props;
  const { snapshot, resolve } = useVariantComboInputs(viewCtx, combo);
  const tpl = snapshot.tpl ? resolve(snapshot.tpl) : undefined;
  const indicatedVs = snapshot.setting ? resolve(snapshot.setting) : undefined;

  const contextMenuProps = useContextMenu({
    menu: () => {
      const builder = new MenuBuilder();
      builder.genSection(undefined, (push) => {
        push(
          <Menu.Item
            onClick={async () => {
              if (onActivate) {
                const frame = viewCtx.studioCtx.focusedFrame();
                if (frame) {
                  return viewCtx.change(() =>
                    viewCtx.getViewOps().clearFrameComboSettings(frame),
                  );
                }
                onActivate();
              }
            }}
            key={`clear-combo-settings`}
          >
            <MenuItemContent>
              <UiText message={"Clear settings for this combo"} />
            </MenuItemContent>
          </Menu.Item>,
        );
      });
      return builder.build({
        menuName: "variant-combo-item-menu",
      });
    },
  });

  return (
    <PlasmicVariantComboRow
      labelContainer={snapshot.labels.map((label) => (
        <Chip key={label.uuid}>{label.name}</Chip>
      ))}
      root={{ onClick, ...contextMenuProps }}
      visibleButton={
        onActivate
          ? {
              onClick: (e) => {
                e.stopPropagation();
                onActivate();
              },
            }
          : { render: () => null }
      }
      isIndicated={!!indicatedVs}
      indicator={
        indicatedVs && tpl
          ? {
              popover: () => (
                <VariantSettingPopoverContent
                  site={viewCtx.site}
                  tpl={tpl}
                  vs={indicatedVs}
                  viewCtx={viewCtx}
                />
              ),

              popoverTitle: () => (
                <VariantSettingPopoverTitle vs={indicatedVs} viewCtx={viewCtx}>
                  <VariantComboSettingsCaption tpl={tpl} setting={indicatedVs} viewCtx={viewCtx} />
                </VariantSettingPopoverTitle>
              ),

              placement: "left",
            }
          : undefined
      }
    />
  );
};

export default VariantComboRow;

const VariantComboSettingsCaption = React.memo(function VariantComboSettingsCaption({ tpl, setting, viewCtx }: { tpl: TplNode; setting: VariantSetting; viewCtx: ViewCtx }) {
  const recipe = React.useCallback<CanvasViewFieldRecipe>((field) => indicatorFields(field, [], setting, tpl), [setting, tpl]);
  const readCaption = React.useCallback(() => String(summarizeTpl(tpl, isTplVariantable(tpl) ? getEffectiveVariantSetting(tpl, setting.variants).rsh() : undefined)), [tpl, setting]);
  const caption = useCanvasComponentValue(viewCtx.studioCtx, setting, recipe, readCaption);
  return caption === undefined ? null : <UiText message="Settings for element {part1}" values={{ part1: caption }} />;
});
